1	import Link from "next/link";
2	import { notFound } from "next/navigation";
3	import { Prisma } from "@prisma/client";
4	import { db } from "@/lib/db";
5	import { getAdminUser } from "@/lib/auth";
6	import {
7	  Empty,
8	  Panel,
9	  StatTile,
10	  TableFrame,
11	  Th,
12	  formatDate,
13	  formatDateTime,
14	  severityClass,
15	  truncate,
16	} from "./ui";
17	
18	export const dynamic = "force-dynamic";
19	
20	const PAGE_SIZE = 25;
21	
22	// ── Caps ──────────────────────────────────────────────────────────────────
23	// Two of the views filter Project by an id set assembled from another table.
24	// Both sets are small by nature — a flagged site is the exception, a taken-down
25	// site more so — but "small by nature" is not a bound, and an unbounded IN ()
26	// list is how a page like this dies quietly a year from now. Each cap is
27	// surfaced in the UI when it actually bites, rather than silently truncating.
28	const FLAGGED_SITE_CAP = 2000;
29	const TAKEN_DOWN_CAP = 2000;
30	
31	type View = "live" | "flagged" | "down";
32	
33	const VIEWS: Record<View, { label: string; blurb: string }> = {
34	  live: {
35	    label: "Live",
36	    blurb: "Every project with publishedAt set — the sites currently resolving on *.kodely.site.",
37	  },
38	  flagged: {
39	    label: "Needs review",
40	    blurb: "Live sites carrying at least one moderation finding nobody has ruled on yet.",
41	  },
42	  down: {
43	    label: "Taken down",
44	    blurb:
45	      "Projects an operator took offline from this panel and which are still offline. Read out of AdminAuditLog — publishedAt alone cannot tell a takedown from a site that was never published.",
46	  },
47	};
48	
49	function isView(v: unknown): v is View {
50	  return typeof v === "string" && v in VIEWS;
51	}
52	
53	type SortKey = "recent" | "oldest" | "slug" | "updated";
54	
55	/**
56	 * DATABASE-NATIVE sorts only, for the same reason app/admin/users/page.tsx
57	 * gives: finding count, file count and last build are all rolled up per PAGE
58	 * from other tables, so offering "sort by findings" would sort 25 arbitrary
59	 * rows and look like it had sorted the registry. The "Needs review" view is the
60	 * honest version of that request — it filters in the database instead.
61	 */
62	const SORTS: Record<SortKey, { label: string; orderBy: Prisma.ProjectOrderByWithRelationInput }> = {
63	  recent: { label: "Newest publish", orderBy: { publishedAt: "desc" } },
64	  oldest: { label: "Oldest publish", orderBy: { publishedAt: "asc" } },
65	  updated: { label: "Recently changed", orderBy: { updatedAt: "desc" } },
66	  slug: { label: "Slug", orderBy: { slug: "asc" } },
67	};
68	
69	function isSortKey(v: unknown): v is SortKey {
70	  return typeof v === "string" && v in SORTS;
71	}
72	
73	function first(v: string | string[] | undefined): string {
74	  if (Array.isArray(v)) return v[0] ?? "";
75	  return v ?? "";
76	}
77	
78	function href(params: { q: string; view: View; sort: SortKey; page: number }): string {
79	  const sp = new URLSearchParams();
80	  if (params.q) sp.set("q", params.q);
81	  if (params.view !== "live") sp.set("view", params.view);
82	  if (params.sort !== "recent") sp.set("sort", params.sort);
83	  if (params.page > 1) sp.set("page", String(params.page));
84	  const qs = sp.toString();
85	  return qs ? `/admin/sites?${qs}` : "/admin/sites";
86	}
87	
88	// ── Per-page rollups ──────────────────────────────────────────────────────
89	// Everything below is keyed by projectId and fetched for the CURRENT PAGE ONLY,
90	// in a fixed number of queries regardless of how many sites are on it. No query
91	// ever runs inside a loop over rows.
92	
93	type FindingRollupRow = {
94	  projectId: string;
95	  total: number;
96	  high: number;
97	  medium: number;
98	  low: number;
99	  blocked: number;
100	  unreviewed: number;
101	  falsePositive: number;
102	  lastFindingAt: Date | null;
103	};
104	
105	type RuleAccuracyRow = {
106	  rule: string;
107	  total: number;
108	  sites: number;
109	  high: number;
110	  medium: number;
111	  low: number;
112	  blocked: number;
113	  reviewed: number;
114	  truePositive: number;
115	  falsePositive: number;
116	};
117	
118	type Rollup = {
119	  findings: FindingRollupRow | null;
120	  files: number;
121	  builds: number;
122	  lastBuildAt: Date | null;
123	  takenDownAt: Date | null;
124	};
125	
126	export default async function AdminSitesPage({
127	  searchParams,
128	}: {
129	  searchParams: Promise<{ [key: string]: string | string[] | undefined }>;
130	}) {
131	  // Defense in depth — app/admin/layout.tsx is the primary gate, but a layout
132	  // is not an authorization boundary on its own (it does not re-render on every
133	  // navigation within the section). 404 rather than redirect, so a non-admin
134	  // learns nothing about this path. Same idiom as every other page here.
135	  if (!(await getAdminUser())) notFound();
136	
137	  const sp = await searchParams;
138	  const q = first(sp.q).trim();
139	  const viewRaw = first(sp.view);
140	  const view: View = isView(viewRaw) ? viewRaw : "live";
141	  const sortRaw = first(sp.sort);
142	  const sort: SortKey = isSortKey(sortRaw) ? sortRaw : "recent";
143	  const pageRaw = Number.parseInt(first(sp.page), 10);
144	  const page = Number.isFinite(pageRaw) && pageRaw > 0 ? pageRaw : 1;
145	
146	  // ── Whole-table figures, and the id sets the two filtered views need ─────
147	  // ModerationFinding has no relation to Project (see prisma/schema.prisma), so
148	  // "which sites are flagged" cannot be a join in the Project query — it is one
149	  // grouped read of the findings table, done once here, not once per row.
150	  const [liveCount, findingTotal, unreviewedTotal, flaggedGroups, takenDownRows] =
151	    await Promise.all([
152	      db.project.count({ where: { publishedAt: { not: null } } }),
153	      db.moderationFinding.count(),
154	      db.moderationFinding.count({ where: { reviewedAt: null } }),
155	      db.moderationFinding.groupBy({
156	        by: ["projectId"],
157	        where: { reviewedAt: null },
158	        orderBy: { projectId: "asc" },
159	        take: FLAGGED_SITE_CAP,
160	      }),
161	      // Takedown is not a column — clearing publishedAt is indistinguishable
162	      // from "never published". The audit row written alongside it is the only
163	      // record that a takedown happened, so this view reads from there.
164	      db.$queryRaw<{ targetId: string; takenDownAt: Date }[]>`
165	        SELECT a."targetId", MAX(a."createdAt") AS "takenDownAt"
166	        FROM "AdminAuditLog" a
167	        WHERE a."action" = 'site.taken_down' AND a."targetType" = 'project'
168	          AND a."targetId" IS NOT NULL
169	        GROUP BY a."targetId"
170	        ORDER BY MAX(a."createdAt") DESC
171	        LIMIT ${TAKEN_DOWN_CAP}`,
172	    ]);
173	
174	  const flaggedIds = flaggedGroups.map((g) => g.projectId);
175	  const takenDownAt = new Map(takenDownRows.map((r) => [r.targetId, r.takenDownAt]));
176	
177	  // Search is by the two things an abuse report actually gives you: the
178	  // subdomain, or the person who owns it. Raw project id is accepted too, for
179	  // pasting straight out of a log line.
180	  const search: Prisma.ProjectWhereInput[] = q
181	    ? [
182	        {
183	          OR: [
184	            { slug: { contains: q, mode: "insensitive" } },
185	            { name: { contains: q, mode: "insensitive" } },
186	            { user: { email: { contains: q, mode: "insensitive" } } },
187	            { id: q },
188	          ],
189	        },
190	      ]
191	    : [];
192	
193	  const scope: Prisma.ProjectWhereInput =
194	    view === "down"
195	      ? { publishedAt: null, id: { in: [...takenDownAt.keys()] } }
196	      : view === "flagged"
197	        ? { publishedAt: { not: null }, id: { in: flaggedIds } }
198	        : { publishedAt: { not: null } };
199	
200	  const where: Prisma.ProjectWhereInput = { ...scope, AND: search };
201	
202	  // publishedAt is null in the "Taken down" view, so ordering by it there would
203	  // be ordering by nothing. Project.updatedAt is bumped by the takedown write
204	  // itself (@updatedAt), which makes it the closest database-native stand-in for
205	  // takedown recency; the exact audit timestamp is shown per row.
206	  const orderBy: Prisma.ProjectOrderByWithRelationInput[] =
207	    view === "down"
208	      ? [{ updatedAt: "desc" }, { id: "asc" }]
209	      : // `id` breaks ties so pagination is stable when timestamps collide.
210	        [SORTS[sort].orderBy, { id: "asc" }];
211	
212	  const [total, projects] = await Promise.all([
213	    db.project.count({ where }),
214	    db.project.findMany({
215	      where,
216	      orderBy,
217	      skip: (page - 1) * PAGE_SIZE,
218	      take: PAGE_SIZE,
219	      select: {
220	        id: true,
221	        name: true,
222	        slug: true,
223	        createdAt: true,
224	        updatedAt: true,
225	        publishedAt: true,
226	        // A relation select, not a per-row lookup — Prisma resolves this for the
227	        // whole page in one additional statement.
228	        user: { select: { id: true, email: true } },
229	      },
230	    }),
231	  ]);
232	
233	  const ids = projects.map((p) => p.id);
234	
235	  // Three grouped reads for the page, in parallel. Not three per row.
236	  const [findingRows, buildRows, fileRows, ruleRows] = await Promise.all([
237	    ids.length
238	      ? db.$queryRaw<FindingRollupRow[]>`
239	          SELECT f."projectId",
240	                 COUNT(*)::int AS "total",
241	                 COUNT(*) FILTER (WHERE f."severity" = 'high')::int AS "high",
242	                 COUNT(*) FILTER (WHERE f."severity" = 'medium')::int AS "medium",
243	                 COUNT(*) FILTER (WHERE f."severity" = 'low')::int AS "low",
244	                 COUNT(*) FILTER (WHERE f."action" = 'blocked')::int AS "blocked",
245	                 COUNT(*) FILTER (WHERE f."reviewedAt" IS NULL)::int AS "unreviewed",
246	                 COUNT(*) FILTER (WHERE f."outcome" = 'false_positive')::int AS "falsePositive",
247	                 MAX(f."createdAt") AS "lastFindingAt"
248	          FROM "ModerationFinding" f
249	          WHERE f."projectId" IN (${Prisma.join(ids)})
250	          GROUP BY f."projectId"`
251	      : Promise.resolve([]),
252	    ids.length
253	      ? db.build.groupBy({
254	          by: ["projectId"],
255	          where: { projectId: { in: ids } },
256	          _count: { _all: true },
257	          _max: { createdAt: true },
258	        })
259	      : Promise.resolve([]),
260	    // The file count that matters on this page is what is actually SERVED:
261	    // published build output. Draft rows and the Vite source tree are neither
262	    // reachable at the subdomain nor relevant to a takedown decision.
263	    ids.length
264	      ? db.projectFile.groupBy({
265	          by: ["projectId"],
266	          where: { projectId: { in: ids }, published: true, kind: "build" },
267	          _count: { _all: true },
268	        })
269	      : Promise.resolve([]),
270	    // Whole-table, not per-page: this panel is about how good the RULES are,
271	    // which is not a property of whichever 25 sites you are looking at.
272	    db.$queryRaw<RuleAccuracyRow[]>`
273	      SELECT f."rule",
274	             COUNT(*)::int AS "total",
275	             COUNT(DISTINCT f."projectId")::int AS "sites",
276	             COUNT(*) FILTER (WHERE f."severity" = 'high')::int AS "high",
277	             COUNT(*) FILTER (WHERE f."severity" = 'medium')::int AS "medium",
278	             COUNT(*) FILTER (WHERE f."severity" = 'low')::int AS "low",
279	             COUNT(*) FILTER (WHERE f."action" = 'blocked')::int AS "blocked",
280	             COUNT(*) FILTER (WHERE f."reviewedAt" IS NOT NULL)::int AS "reviewed",
281	             COUNT(*) FILTER (WHERE f."outcome" = 'true_positive')::int AS "truePositive",
282	             COUNT(*) FILTER (WHERE f."outcome" = 'false_positive')::int AS "falsePositive"
283	      FROM "ModerationFinding" f
284	      GROUP BY f."rule"
285	      ORDER BY COUNT(*) DESC`,
286	  ]);
287	
288	  const rollups = new Map<string, Rollup>(
289	    ids.map((id) => [
290	      id,
291	      { findings: null, files: 0, builds: 0, lastBuildAt: null, takenDownAt: takenDownAt.get(id) ?? null },
292	    ]),
293	  );
294	  for (const r of findingRows) {
295	    const p = rollups.get(r.projectId);
296	    if (p) p.findings = r;
297	  }
298	  for (const r of buildRows) {
299	    const p = rollups.get(r.projectId);
300	    if (!p) continue;
301	    p.builds = r._count._all;
302	    p.lastBuildAt = r._max.createdAt;
303	  }
304	  for (const r of fileRows) {
305	    const p = rollups.get(r.projectId);
306	    if (p) p.files = r._count._all;
307	  }
308	
309	  const pageCount = Math.max(1, Math.ceil(total / PAGE_SIZE));
310	  const flaggedCapped = flaggedIds.length >= FLAGGED_SITE_CAP;
311	  const takenDownCapped = takenDownAt.size >= TAKEN_DOWN_CAP;
312	
313	  return (
314	    <div className="mx-auto max-w-6xl px-6 py-10">
315	      <div className="mb-8">
316	        <Link
317	          href="/admin"
318	          className="text-xs text-black/50 underline-offset-4 hover:underline dark:text-white/50"
319	        >
320	          ← kodely admin
321	        </Link>
322	        <div className="mt-1 text-lg font-semibold tracking-tight">Published sites</div>
323	        <p className="text-sm text-black/60 dark:text-white/60">
324	          Everything currently reachable on <span className="font-mono text-xs">*.kodely.site</span>,
325	          what the abuse scanner flagged on it, and the one lever that takes it offline.
326	        </p>
327	      </div>
328	
329	      {findingTotal === 0 ? (
330	        <div className="mb-6 rounded-xl border border-amber-500/40 bg-amber-500/5 p-5 text-sm">
331	          <h2 className="text-sm font-medium text-amber-700 dark:text-amber-500">
332	            The findings table is empty — that is not the same as &ldquo;no abuse&rdquo;
333	          </h2>
334	          <p className="mt-2 text-black/70 dark:text-white/70">
335	            Nothing has ever written a <span className="font-mono text-xs">ModerationFinding</span>{" "}
336	            row. <span className="font-mono text-xs">lib/moderation.ts</span> runs on every publish
337	            and <span className="font-mono text-xs">app/api/projects/[id]/publish/route.ts</span>{" "}
338	            still only <span className="font-mono text-xs">console.warn</span>s the sub-blocking
339	            findings, so they exist in the logs and nowhere else. Read an empty findings column below
340	            as <em>&ldquo;never recorded&rdquo;</em>, never as <em>&ldquo;came back clean&rdquo;</em>
341	            . Blocking (<span className="font-mono text-xs">high</span>) findings never reach this
342	            table at all, by construction: the publish is refused, so the site was never live.
343	          </p>
344	        </div>
345	      ) : null}
346	
347	      <div className="mb-6 grid grid-cols-2 gap-4 sm:grid-cols-5">
348	        <StatTile label="Live sites" value={liveCount} hint="publishedAt is set" />
349	        <StatTile
350	          label="Sites needing review"
351	          value={flaggedIds.length}
352	          tone={flaggedIds.length > 0 ? "warn" : undefined}
353	          hint={flaggedCapped ? `capped at ${FLAGGED_SITE_CAP}` : "≥1 unruled finding"}
354	        />
355	        <StatTile label="Findings recorded" value={findingTotal} />
356	        <StatTile
357	          label="Unreviewed findings"
358	          value={unreviewedTotal}
359	          tone={unreviewedTotal > 0 ? "warn" : undefined}
360	        />
361	        <StatTile
362	          label="Taken down"
363	          value={takenDownAt.size}
364	          hint={takenDownCapped ? `capped at ${TAKEN_DOWN_CAP}` : "from the audit log"}
365	        />
366	      </div>
367	
368	      <div className="mb-4 flex flex-wrap gap-2">
369	        {(Object.keys(VIEWS) as View[]).map((v) => (
370	          <Link
371	            key={v}
372	            href={href({ q, view: v, sort, page: 1 })}
373	            aria-current={v === view ? "page" : undefined}
374	            className={`rounded-xl border px-3 py-1.5 text-sm ${
375	              v === view
376	                ? "border-black/40 font-medium dark:border-white/40"
377	                : "border-black/10 text-black/60 hover:bg-black/5 dark:border-white/10 dark:text-white/60 dark:hover:bg-white/5"
378	            }`}
379	          >
380	            {VIEWS[v].label}
381	          </Link>
382	        ))}
383	      </div>
384	      <p className="mb-6 text-xs text-black/50 dark:text-white/50">{VIEWS[view].blurb}</p>
385	
386	      <form method="get" action="/admin/sites" className="mb-6 flex flex-wrap items-center gap-2">
387	        {view !== "live" ? <input type="hidden" name="view" value={view} /> : null}
388	        <input
389	          type="search"
390	          name="q"
391	          defaultValue={q}
392	          placeholder="Search slug, owner email or project id"
393	          aria-label="Search published sites"
394	          className="w-full max-w-sm rounded-xl border border-black/10 bg-transparent px-3 py-2 text-sm outline-none placeholder:text-black/40 focus:border-black/30 dark:border-white/10 dark:placeholder:text-white/40 dark:focus:border-white/30"
395	        />
396	        <select
397	          name="sort"
398	          defaultValue={sort}
399	          aria-label="Sort sites"
400	          disabled={view === "down"}
401	          className="rounded-xl border border-black/10 bg-transparent px-3 py-2 text-sm outline-none disabled:opacity-40 dark:border-white/10"
402	        >
403	          {(Object.keys(SORTS) as SortKey[]).map((k) => (
404	            <option key={k} value={k}>
405	              {SORTS[k].label}
406	            </option>
407	          ))}
408	        </select>
409	        <button
410	          type="submit"
411	          className="rounded-xl border border-black/10 px-3 py-2 text-sm font-medium hover:bg-black/5 dark:border-white/10 dark:hover:bg-white/5"
412	        >
413	          Search
