// Throwaway fixture for verifying the admin takedown path end to end.
// Everything it creates is namespaced `zz-td-<stamp>` and removed by teardown.js.
require("dotenv").config({ path: require("path").join(process.cwd(), ".env") });
const { PrismaClient } = require("@prisma/client");
const { randomBytes, createHash } = require("node:crypto");
const fs = require("node:fs");

const db = new PrismaClient();
const stamp = Date.now().toString(36);
const tag = `zz-td-${stamp}`;

function hashToken(t) {
  return createHash("sha256").update(t).digest("hex");
}

(async () => {
  const admin = await db.user.create({
    data: { email: `${tag}-admin@example.invalid`, name: "TD Verify Admin", role: "ADMIN" },
  });
  const owner = await db.user.create({
    data: { email: `${tag}-owner@example.invalid`, name: "TD Verify Owner", role: "CUSTOMER" },
  });

  const token = randomBytes(32).toString("base64url");
  await db.session.create({
    data: {
      userId: admin.id,
      tokenHash: hashToken(token),
      expiresAt: new Date(Date.now() + 86400000),
    },
  });

  const project = await db.project.create({
    data: {
      userId: owner.id,
      name: "TD Verify Site",
      slug: tag,
      publishedAt: new Date(),
    },
  });

  await db.projectFile.createMany({
    data: [
      // Published build output — what the public subdomain serves.
      {
        projectId: project.id,
        path: "index.html",
        content: "<!doctype html><html><head></head><body><h1>td-verify-live</h1></body></html>",
        published: true,
        kind: "build",
      },
      {
        projectId: project.id,
        path: "assets/app.css",
        content: "h1{color:#111}",
        published: true,
        kind: "build",
      },
      // Draft build output — the preview.
      {
        projectId: project.id,
        path: "index.html",
        content: "<!doctype html><html><body><h1>td-verify-draft</h1></body></html>",
        published: false,
        kind: "build",
      },
      // The owner's real working tree.
      {
        projectId: project.id,
        path: "src/App.tsx",
        content: "export default function App(){return <h1>td-verify-source</h1>}",
        published: false,
        kind: "source",
      },
    ],
  });

  const build = await db.build.create({
    data: {
      projectId: project.id,
      status: "SUCCEEDED",
      model: "verify",
      prompt: "verify",
      endedAt: new Date(),
    },
  });

  const finding = await db.moderationFinding.create({
    data: {
      projectId: project.id,
      rule: "password-form-on-static-site",
      severity: "low",
      path: "index.html",
      evidence: "td-verify evidence snippet",
      action: "recorded",
    },
  });

  const state = {
    tag,
    adminId: admin.id,
    adminEmail: admin.email,
    ownerId: owner.id,
    projectId: project.id,
    slug: project.slug,
    buildId: build.id,
    findingId: finding.id,
    sessionToken: token,
  };
  fs.writeFileSync(`${__dirname}/state.json`, JSON.stringify(state, null, 2));
  console.log(JSON.stringify(state, null, 2));
  await db.$disconnect();
})().catch(async (e) => {
  console.error(e);
  await db.$disconnect();
  process.exit(1);
});

